      const a = asteroids[i];
      a.x -= a.speed;
      if (a.x + a.r < 0) asteroids.splice(i, 1);
      else if (checkCollision(a)) {
        asteroids.splice(i, 1);
        shield--;
        playCollision();
        if (shield <= 0) {
          gameOver = true;
        }
      }
    }

    // move stars
    for (let i = stars.length - 1; i >= 0; i--) {
      const s = stars[i];
      s.x -= s.speed;
      if (s.x < 0) stars.splice(i, 1);
    }

    score += 0.05;
}

